import type { Request, Response, NextFunction } from "express";
import axios from "axios";
import "dotenv/config";

async function streamLog(message: string, level: string, url: string, browser: string, os: string, stackTrace?: string) {
  try {
    const payload = {
      apiKey: process.env.LOGSTREAM_API_KEY,
      message, level, url, browser, os,
      ...(stackTrace && { stackTrace })
    };
    await axios.post(process.env.LOGSTREAM_INGEST_URL, payload);
  } catch (err) {
    console.error("⚠️ LogStream transmission dropped:", err.message);
  }
}

export const logstreamLogger = (req: Request, res: Response, next: NextFunction) => {
  const startTime = Date.now();
  res.on("finish", () => {
    const duration = Date.now() - startTime;
    const routeUrl = req.route ? `${req.baseUrl}${req.route.path}` : req.originalUrl;
    const msg = `API Transaction: ${req.method} ${routeUrl} -> Status ${res.statusCode} (${duration}ms)`;

    streamLog(msg, res.statusCode < 400 ? "INFO" : "WARNING", routeUrl, "Server Agent", "Linux Instance");
  });
  next();
};

