import { Injectable, NestInterceptor, ExecutionContext, CallHandler } from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import axios from 'axios';

@Injectable()
export class LogstreamInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const ctx = context.switchToHttp();
    const request = ctx.getRequest();
    const response = ctx.getResponse();
    const startTime = Date.now();

    return next.handle().pipe(
      tap(() => {
        const duration = Date.now() - startTime;
        axios.post(process.env.LOGSTREAM_INGEST_URL, {
          apiKey: process.env.LOGSTREAM_API_KEY,
          message: `NestJS Action Success: ${request.method} ${request.url} [${duration}ms]`,
          level: 'INFO',
          url: request.url,
          os: 'NestJS Application Layer'
        }).catch(() => null);
      }),
    );
  }
}

