// app/api/telemetry/route.ts
import { NextResponse } from 'next/server';

export async function POST(request: Request) {
  try {
    const data = await request.json();

    // Forward client exceptions or application context logs safely to your gateway
    const response = await fetch(process.env.LOGSTREAM_INGEST_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        apiKey: process.env.LOGSTREAM_API_KEY,
        level: data.level || 'INFO',
        message: `Next.js App Router Signal: ${data.message}`,
        url: data.url || request.url,
        os: 'Vercel Edge Ingestion Engine'
      }),
    });

    return NextResponse.json({ success: response.ok });
  } catch (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

