package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"os"
	"time"
)

func LogstreamMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)

		payload := map[string]interface{}{
			"apiKey":  os.Getenv("LOGSTREAM_API_KEY"),
			"message": "Go Net/HTTP Request Processed successfully",
			"level":   "INFO",
			"url":     r.URL.Path,
			"os":      "Go Routine Linux Kernel",
		}

		body, _ := json.Marshal(payload)
		go http.Post(os.Getenv("LOGSTREAM_INGEST_URL"), "application/json", bytes.NewBuffer(body))
	})
}

