window.addEventListener('error', (event) => {
  const telemetryPayload = {
    apiKey: "YOUR_PUBLIC_WORKSPACE_API_KEY",
    message: `Uncaught Browser Exception: ${event.message}`,
    level: "CRITICAL",
    url: window.location.href,
    browser: navigator.userAgent,
    os: navigator.platform,
    stackTrace: event.error ? event.error.stack : null
  };

  fetch("https://logstream-ops-backend.onrender.com/api/ingest", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(telemetryPayload)
  }).catch((err) => console.warn("Telemetry dropped", err));
});

