import { FastifyInstance } from 'fastify';
import axios from 'axios';

export async function logstreamPlugin(fastify: FastifyInstance) {
  fastify.addHook('onResponse', async (request, reply) => {
    try {
      await axios.post(process.env.LOGSTREAM_INGEST_URL, {
        apiKey: process.env.LOGSTREAM_API_KEY,
        message: `Fastify Engine Pipeline Match: ${request.method} -> HTTP ${reply.statusCode}`,
        level: reply.statusCode >= 400 ? 'ERROR' : 'INFO',
        url: request.url,
        os: 'Node Light-Weight V8 Context'
      });
    } catch (err) {
      fastify.log.error('LogStream Dispatch Drop');
    }
  });
}
